func TestQuoteRejections(t *testing.T) {
	now, _ := fixedClock(at(5))
	b := NewBook(WithClock(now))
	if err := b.RegisterVersion(RegisterRequest{ItemID: "seat", VersionID: "future", UnitPrice: 1, Start: at(10)}); err != nil {
