			*views[i].End = at(1000)
			*views[i].EffectiveEnd = at(1000)
		}
		if views[i].VersionID == "new" {
			*views[i].End = at(1000)
			*views[i].EffectiveEnd = at(1000)
		}
	}

	again, _ := b.ItemVersions("seat")
	for _, v := range again {
